import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

public class ZonedDateTimeField_set_TriageGen2Test {

    /**
     * Tests the set method with a valid date string and a specific locale.
     * This covers the standard execution path: UTC -> Local -> Set Field -> Local -> UTC.
     */
    @Test
    public void testSet_ValidDateString_ReturnsCorrectInstant() {
        DateTimeZone zone = DateTimeZone.forID("America/New_York");
        DateTime initialDateTime = new DateTime(2023, 5, 10, 10, 0, 0, zone);
        long initialInstant = initialDateTime.getMillis();

        // We use a ZonedDateTimeField via a DateTime instance for testing purposes
        // Since ZonedDateTimeField is an inner class, we access its behavior through a DateTime object
        // that is tied to a ZonedChronology.
        DateTime targetDateTime = new DateTime(initialInstant, zone);
        ZonedChronology.ZonedDateTimeField field = targetDateTime.dayOfMonth();

        // Set the field using a string representation of a day (e.g., "15")
        // Note: The behavior of 'set(long, String, Locale)' depends on the specific field type.
        // If we use the dayOfMonth field, 'text' should represent a day.
        String text = "15";
        Locale locale = Locale.ENGLISH;

        long newInstant = field.set(initialInstant, text, locale);

        // Verify the result
        DateTime resultDateTime = new DateTime(newInstant, zone);
        Assert.assertEquals(15, resultDateTime.getDayOfMonth());
        Assert.assertEquals(initialDateTime.getYear(), resultDateTime.getYear());
        Assert.assertEquals(initialDateTime.getMonthOfYear(), resultDateTime.getMonthOfYear());
    }

    /**
     * Tests the set method with a different locale to ensure locale-specific parsing.
     */
    @Test
    public void testSet_WithDifferentLocale() {
        DateTimeZone zone = DateTimeZone.UTC;
        long instant = 1672531200000L; // 2023-01-01
        DateTime targetDateTime = new DateTime(instant, zone);
        ZonedChronology.ZonedDateTimeField field = targetDateTime.monthOfYear();

        // Using French locale for month name (though monthOfYear usually expects numeric text or specific formats)
        // For simplicity, we test if the method handles the locale parameter without throwing exceptions
        // and processes the text correctly.
        String text = "JANUARY"; 
        Locale locale = Locale.ENGLISH;

        long newInstant = field.set(instant, text, locale);
        DateTime resultDateTime = new DateTime(newInstant, zone);

        Assert.assertEquals(1, resultDateTime.getMonthOfYear());
    }

    /**
     * Tests the set method with a value that triggers leniency (e.g., setting day 31 in a 30-day month).
     * This checks the "lenient" aspect mentioned in the method comments.
     */
    @Test
    public void testSet_LenientBehavior() {
        DateTimeZone zone = DateTimeZone.UTC;
        // 2023-04-01 (April has 30 days)
        long instant = 1680307200000L; 
        DateTime targetDateTime = new DateTime(instant, zone);
        ZonedChronology.ZonedDateTimeField field = targetDateTime.dayOfMonth();

        // Set day to 31. In lenient mode, this should roll over to May 1st.
        String text = "31";
        long newInstant = field.set(instant, text, Locale.ENGLISH);

        DateTime resultDateTime = new DateTime(newInstant, zone);
        // April 30 + 1 day = May 1
        Assert.assertEquals(5, resultDateTime.getMonthOfYear());
        Assert.assertEquals(1, resultDateTime.getDayOfMonth());
    }

    /**
     * Tests the set method with an invalid string to ensure it handles/throws appropriately
     * based on the underlying iField implementation.
     */
    @Test(expected = IllegalArgumentException.class)
    public void testSet_InvalidText_ThrowsException() {
        DateTimeZone zone = DateTimeZone.UTC;
        long instant = 1680307200000L;
        DateTime targetDateTime = new DateTime(instant, zone);
        ZonedChronology.ZonedDateTimeField field = targetDateTime.dayOfMonth();

        // Providing non-numeric text for a numeric field
        field.set(instant, "not-a-number", Locale.ENGLISH);
    }

    /**
     * Tests the set method with a long instant representing a different time zone to ensure
     * the conversion between UTC and Local (iZone.convertUTCToLocal) is handled.
     */
    @Test
    public void testSet_TimeZoneConversion() {
        // Tokyo is UTC+9
        DateTimeZone zone = DateTimeZone.forID("Asia/Tokyo");
        // 2023-01-01 00:00:00 Tokyo time is 2022-12-31 15:00:00 UTC
        long instant = zone.parseDateTime("2023-01-01T00:00:00").getMillis();

        DateTime targetDateTime = new DateTime(instant, zone);
        ZonedChronology.ZonedDateTimeField field = targetDateTime.hourOfDay();

        // Set hour to 12
        long newInstant = field.set(instant, "12", Locale.ENGLISH);

        DateTime resultDateTime = new DateTime(newInstant, zone);
        Assert.assertEquals(12, resultDateTime.getHourOfDay());

        // Verify UTC conversion back is correct
        // 12:00 Tokyo = 03:00 UTC
        DateTime utcResult = new DateTime(newInstant, DateTimeZone.UTC);
        Assert.assertEquals(3, utcResult.getHourOfDay());
    }
}
